const LAY=(()=>{/* ASK 364 rev 2 (operator 01:21 CST 11-17: "why wasn't the defender forced to prove their position with the layers"; plan Wall 7641, rev 2 Wall 7647; reads W1 7644/7650, W2 7645/7652, W3 7646/7649; rev 2 answers W1's FAIL at Wall 7653, F1 to F5): the layers check on the defender's own round, computed by code. Each critical point reads at least two verses together, each quoted with its reference on an [L1] or [L3] line, at least one [L1] (single verse doctrine is prohibited; amended C1, W1 7656, W2, W3); a limiting word added in the defender's own MEANS row stands in the KJV words of a verse quoted on that row (an [L2] gloss carries nothing). LIMIT: only the listed words are caught. */
 const LIM=['at all','only','never','none','all','alone','solely','any','every','no','entirely','wholly','exclusively','always','nothing','without'];
 const NEG=/\b(?:not|no|neither|nor|none)\b/i;const NEGW=['no','none','any'];const WIDEN=['only','alone','solely'];const TXT=/^(?:bible|bibles|record|kjv|text|debate|canon|book)\b/;const DESC=/^(?:stated|states|state|named|names|written|writes|record|record's|text|text's|says|speaks|carrying|carries|register)$/;
 const W=s=>' '+String(s||'').toLowerCase().replace(/[‘’']/g,"'").replace(/[^a-z' ]+/g,' ').replace(/\s+/g,' ').trim()+' ';
 const REFS='(?:[1-3]\\s)?[A-Z][a-z]+(?:\\sof\\s[A-Z][a-z]+)?\\.?\\s\\d{1,3}:\\d{1,3}';const REFG=new RegExp(REFS,'g');
 const CP=/^[\s#>*_-]*(?:(?:\d{1,2}|[IVX]{1,5})[.)]\s*[*_]*\s*)?(?:LINK\s+(?:\d+|[A-Z])\b|(?:Answer|ANSWER)\b[^\n]{0,40}\bpress|PREMISE\s+\d+\b|D\d+\s*(?:--|:|—|–|\.(?!\d)|\()|PRESS(?:ES)?\b)|^\s*#{1,6}\s*[*_]*\s*(?:(?:\d{1,2}|[IVX]{1,5})[.)]|Point\s+\d+\b)/i; /* rev 2.3 (W3 7674): a numbered or roman prefix before LINK, PREMISE or Dn; a numbered, roman or "Point n" heading; a PRESS head (not PRESSED) */ /* a PRESSED WITH list is not read here: its rows name the round that proves them (PROVEN IN); their MEANS words are read */const MD=/^\s*#{1,6}\s/;const WD=/\b(?:correction|corrects?|correcting|withdraw(?:s|n|al|ing)?|withdrew|retract(?:s|ed|ion|ing)?)\b/i,WDN=/\b(?:not|no|never|nor|cannot)\s+(?:\w+\s+){0,2}(?:correct|withdr|retract)/i;
 const Q=/["“]([^"”\n]{6,})["”]/g;
 /* F1: only the defender's own MEANS row: a quoted verse, then an upper-case MEANS: whose text is not itself a quotation, with no press named before it */
 function words(t){const out=[];for(const l of String(t||'').split('\n')){const m=l.match(/MEANS\s*:\s*(.*?)(?:\s--\s|\s\|\s|$)/);if(!m)continue;
   const before=l.slice(0,l.indexOf(m[0]));if(/press/i.test(before))continue;if(/^\s*["“]/.test(m[1]))continue;const vq=[...before.matchAll(Q)].map(x=>x[1]);if(!vq.length)continue;
   const mi=l.indexOf(m[0]),after=l.slice(mi+m[0].length);const l3=[...after.matchAll(Q)].map(x=>x[1]);/* F2 (W3 7654): every KJV quotation on the row after the MEANS text carries too */
   const ct=vq.concat(l3).join(' ');const carried=W(ct);const neg=NEG.test(ct);let means=W(m[1]);const add=[];
   if(means.includes(' at all ')&&!carried.includes(' at all ')){add.push('at all');}means=means.split(' at all ').join(' ');const mw=means.trim().split(' ');
   for(const w of LIM){if(w==='at all')continue;if(carried.includes(' '+w+' ')||(neg&&NEGW.includes(w)))continue;
     let hit=false;mw.forEach((x,i)=>{if(x!==w)return;const pre=mw.slice(Math.max(0,i-6),i);if(WIDEN.includes(w)&&pre.includes('not'))return;/* F2: not only, not ... alone widen */if(TXT.test(mw.slice(i+1,i+2).join(' ')||''))return;/* only said of the Bible or the record, not of the verse */if(mw.slice(Math.max(0,i-3),i+6).some(y=>DESC.test(y)))return;/* W3 7654 3d: a word that describes what the record states adds nothing to the verse */hit=true;});if(hit)add.push(w);}
   if(add.length)out.push({kind:'WORDS',add,line:l.trim().slice(0,600),why:'the MEANS adds '+add.map(x=>'"'+x+'"').join(', ')+', which no KJV words of a verse quoted on that row carry'});}return out;}
 /* amended C1 (W3 7654 4c; W1 7656, W2, W3 agreed): a critical point holds at least two different verses, each quoted with its reference on its own tagged layer line ([L1] or [L3]), at least one [L1]; an [L2] never counts and a reference in prose does not count. The ANSWER row (ANSWER: Ref -- Dn -- "verse") and the MEANS row (Ref "verse" -- MEANS:) read as [L1] lines with their reference. LIMIT: two verses of one sentence count as two. */
 const R1=new RegExp(REFS,'g'),QO=/["“][^"”\n]{6,}["”]/,ANS=new RegExp('^[\\s*_>-]*ANSWER\\s*:\\s*('+REFS+')[^\\n]{0,40}?(?:--|—)\\s*D\\d+\\s*(?:--|—)[\\s*]*["“][^"”\\n]{6,}["”]'),MR=new RegExp('^[\\s*_>-]*(?:\\[L1\\][\\s*]*)?('+REFS+')[\\s:,*]*["“][^"”\\n]{6,}["”][^\\n]*?\\sMEANS\\s*:');
 const nr=v=>v.replace(/\s+/g,' ').replace(/\.(?=\s)/,'');
 function paired(seg){const out=[];const ms=[...seg.matchAll(R1)];ms.forEach((m,k)=>{const end=m.index+m[0].length,stop=k+1<ms.length?ms[k+1].index:seg.length;const t=seg.slice(end,stop);const qi=t.search(QO);if(qi>=0&&qi<=160&&!/\)/.test(t.slice(0,qi))){out.push(nr(m[0]));return;}const pre=seg.slice(0,m.index);if(/["”][\s,]*\([^()\n]{0,40}$/.test(pre))out.push(nr(m[0]));});return out;}
 function verses(x){const S=new Map();let noref=0;
   for(const l of x.split('\n')){if(!QO.test(l))continue;let m=l.match(ANS)||l.match(MR);if(m){S.set(nr(m[1]),(S.get(nr(m[1]))||'')+'1');}
    const parts=l.split(/(?=\[L[1-4]\])/);for(const seg of parts){const t=seg.match(/^\[L([1-4])\]/);if(!t||(t[1]!=='1'&&t[1]!=='3'))continue;const r=paired(seg);if(!r.length){if(QO.test(seg)&&!R1.test(seg))noref++;R1.lastIndex=0;continue;}r.forEach(v=>S.set(v,(S.get(v)||'')+t[1]));}
    const pw=l.search(/PRESSED WITH\s*:/i);if(pw>=0)paired(l.slice(pw)).forEach(v=>S.set(v,(S.get(v)||'')+'1')); /* rev 2.4 F1 (W1 7678): a PRESSED WITH row Ref -- "words" reads as [L1] */
    let last=0;for(const g of l.matchAll(/\(([^()\n]*\[L[13]\][^()\n]*)\)/g)){const q=[...l.slice(last,g.index).matchAll(new RegExp(QO.source,'g'))].length;last=g.index+g[0].length;let c=0;
     for(const sg of g[1].split(';')){const tg=sg.match(/\[L([13])\]\s*$/);if(!tg||tg[1]!=='1')continue;for(const r of (sg.match(R1)||[])){if(c>=q)break;S.set(nr(r),(S.get(nr(r))||'')+'1');c++;}R1.lastIndex=0;}} /* rev 2.4 F2 (W1 7678): "quote ... (Ref [L1]; ...)": a tag after its reference in the same parenthesis gives that reference the tag; [L1] references take the quotations that stand before the parenthesis, one each */
   }
   return {n:S.size,l1:[...S.values()].some(v=>v.includes('1')),noref};}
 function structure(t){const L=String(t||'').split('\n');const B=[];let cur=null;
   for(const l of L){if(CP.test(l)||MD.test(l)){if(cur)B.push(cur);cur=CP.test(l)?{head:l.trim(),lines:[l]}:null;continue;}if(cur)cur.lines.push(l);}if(cur)B.push(cur);
   const out=[];B.forEach(b=>{const x=b.lines.join('\n');if(x.replace(/\s+/g,' ').trim().length<60)return;if(WD.test(b.head)&&!WDN.test(b.head))return; /* rev 2.4 F3 (W1 7678): a head that corrects or withdraws asserts nothing; "do not withdraw" is still a point */const v=verses(x);if(v.n>=2&&v.l1)return;
    
    out.push({kind:'STRUCTURE',head:b.head.slice(0,300),why:(v.n===0?'no verse quoted with its reference on an [L1] or [L3] line':v.n===1?'one verse only on its layer lines; no further verse is read with it on an [L1] or [L3] line':'no [L1] verse among its layer lines')+(v.noref?'; '+v.noref+' tagged verse(s) quoted with no reference on the line (state the reference)':'')});});return out;}
 function check(raw){const t=String(raw||'');if(!t.trim())return {applies:false,items:[]};const items=structure(t).concat(words(t)).map((x,i)=>({id:'L'+(i+1),...x}));return {applies:true,items,pass:!items.length};}
 function note(c,after){/* after: the BARRED MOVES note follows this one in the same resend and closes it with the one-request line, so it is said once (W1 N3) */return 'LAYERS CHECK -- computed by the system from your round, not by a model (PROVEN STRUCTURE, rulings 397 to 400: the layers are the language of this debate). Each critical point below is short of its layers. Single verse doctrine is prohibited (Isaiah 28:10): a critical point reads at least two verses together. For each verse, write its reference and then quote its KJV words, on an [L1] or [L3] line ([L1] the verse, [L3] the further verse it is read with). A reference with no quoted words does not count, and an [L2] gloss is welcome but does not stand in place of a verse. A limiting word you add in your own MEANS (such as only, never, all, at all, without) must stand in the KJV words of a verse quoted on that row; a lexicon gloss does not carry it.\n'
   +'Write your whole round again, the same case, and for each point below add what it lacks, or take the added word out. The points:\n'
   +c.items.map(x=>x.id+' '+(x.kind==='WORDS'?'MEANS row: "'+x.line.slice(0,400)+'"':'"'+x.head.slice(0,200)+'"')+' -- '+x.why).join('\n')
   +(after?'':'\nReturn the whole round; this is the only request of its kind.');}
 function bare(items){return items.map(x=>'\n[SYSTEM LAYERS CHECK] BARE CLAIM: '+(x.kind==='WORDS'?'MEANS row "'+x.line.slice(0,300)+'"':'"'+x.head.slice(0,200)+'"')+' -- '+x.why+'; at a critical point it carries no weight (rulings 397 to 400).').join('');}
 return {check,note,bare,words,structure};})();
